use std::collections::BTreeMap;
use std::fmt::Write;
use std::fs;
use std::path::Path;

const GENERATED_HEADER: &str = "\
// THIS FILE IS AUTO-GENERATED. DO NOT EDIT.\n\
// Generated by objectiveai-cli-builder from objectiveai-json-schema/.\n";

/// Tree node: children are snake_case namespaces, schemas are PascalCase leaf names.
#[derive(Default)]
struct TreeNode {
    children: BTreeMap<String, TreeNode>,
    /// PascalCase name → schema filename (e.g. "Agent" → "agent.Agent.json")
    schemas: BTreeMap<String, String>,
}

fn main() {
    let schema_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../objectiveai-json-schema");
    let out_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../src/schemas");

    // Clean old auto-generated files (depth-first)
    clean_generated(&out_dir);

    // Read schema titles from filenames
    let mut root = TreeNode::default();
    for entry in fs::read_dir(&schema_dir).unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let filename = path.file_name().unwrap().to_str().unwrap().to_string();
        let title = filename.strip_suffix(".json").unwrap();
        let segments: Vec<&str> = title.split('.').collect();

        let mut node = &mut root;
        for &seg in &segments[..segments.len() - 1] {
            node = node.children.entry(seg.to_string()).or_default();
        }
        let schema_name = segments.last().unwrap().to_string();
        node.schemas.insert(schema_name, filename);
    }

    // Generate the module tree
    fs::create_dir_all(&out_dir).unwrap();
    generate_module(&root, &out_dir, 0);

    println!("Generated schema CLI modules in {}", out_dir.display());
}

/// Recursively delete files with the auto-generated marker, then prune empty dirs.
fn clean_generated(dir: &Path) {
    if !dir.exists() {
        return;
    }
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();
        if path.is_dir() {
            clean_generated(&path);
        } else if path.extension().and_then(|e| e.to_str()) == Some("rs") {
            if let Ok(content) = fs::read_to_string(&path) {
                if content.starts_with(GENERATED_HEADER) {
                    fs::remove_file(&path).unwrap();
                }
            }
        }
    }
    if dir.exists() && fs::read_dir(dir).unwrap().next().is_none() {
        fs::remove_dir(dir).unwrap();
    }
}

/// Generate mod.rs for a tree node.
fn generate_module(node: &TreeNode, dir: &Path, depth: usize) {
    fs::create_dir_all(dir).unwrap();

    // Relative path from this mod.rs to objectiveai-json-schema/
    // depth 0: objectiveai-cli/src/schemas/mod.rs → ../../../objectiveai-json-schema
    // depth 1: objectiveai-cli/src/schemas/agent/mod.rs → ../../../../objectiveai-json-schema
    let ups = "../".repeat(depth + 3);
    let schema_rel = format!("{ups}objectiveai-json-schema");

    let mut code = String::new();
    code.push_str(GENERATED_HEADER);
    code.push('\n');

    // Module declarations
    for child_name in node.children.keys() {
        writeln!(code, "pub mod {child_name};").unwrap();
    }
    if !node.children.is_empty() {
        code.push('\n');
    }

    code.push_str("use clap::Subcommand;\n\n");

    // GetCommand (if there are leaf schemas)
    if !node.schemas.is_empty() {
        code.push_str("#[derive(Subcommand)]\n");
        code.push_str("#[command(rename_all = \"verbatim\")]\n");
        code.push_str("pub enum GetCommand {\n");
        code.push_str("    #[command(name = \"get\")]\n");
        code.push_str("    Get,\n");
        code.push_str("}\n\n");
    }

    // Commands enum
    code.push_str("#[derive(Subcommand)]\n");
    code.push_str("#[command(rename_all = \"verbatim\")]\n");
    code.push_str("pub enum Commands {\n");

    // list
    code.push_str("    #[command(name = \"list\")]\n");
    code.push_str("    List,\n");

    // Child namespace variants
    for child_name in node.children.keys() {
        let variant = to_pascal_case(child_name);
        writeln!(code, "    #[command(name = \"{child_name}\")]").unwrap();
        writeln!(code, "    {variant} {{").unwrap();
        writeln!(code, "        #[command(subcommand)]").unwrap();
        writeln!(code, "        command: {child_name}::Commands,").unwrap();
        writeln!(code, "    }},").unwrap();
    }

    // Schema variants
    for schema_name in node.schemas.keys() {
        writeln!(code, "    {schema_name} {{").unwrap();
        writeln!(code, "        #[command(subcommand)]").unwrap();
        writeln!(code, "        command: GetCommand,").unwrap();
        writeln!(code, "    }},").unwrap();
    }

    code.push_str("}\n\n");

    // Build list of names for the `list` subcommand
    let mut list_items: Vec<&str> = Vec::new();
    for name in node.children.keys() {
        list_items.push(name);
    }
    for name in node.schemas.keys() {
        list_items.push(name);
    }

    // handle() implementation
    code.push_str("impl Commands {\n");
    code.push_str("    pub async fn handle(self, handle: &objectiveai_sdk::cli::output::Handle) -> Result<(), crate::error::Error> {\n");
    code.push_str("        match self {\n");

    code.push_str("            Commands::List => {\n");
    code.push_str("                const NAMES: &[&str] = &[");
    for (i, name) in list_items.iter().enumerate() {
        if i > 0 {
            code.push_str(", ");
        }
        write!(code, "\"{name}\"").unwrap();
    }
    code.push_str("];\n");
    code.push_str("                objectiveai_sdk::cli::output::Output::Notification(\n");
    code.push_str("                    objectiveai_sdk::cli::output::Notification {\n");
    code.push_str("                        agent_id: None,\n");
    code.push_str("                        value: objectiveai_sdk::cli::output::Schemas {\n");
    code.push_str("                            schemas: NAMES.iter().map(|s| s.to_string()).collect(),\n");
    code.push_str("                        }.into(),\n");
    code.push_str("                    },\n");
    code.push_str("                ).emit(handle).await;\n");
    code.push_str("                Ok(())\n");
    code.push_str("            }\n");

    for child_name in node.children.keys() {
        let variant = to_pascal_case(child_name);
        writeln!(
            code,
            "            Commands::{variant} {{ command }} => command.handle(handle).await,"
        )
        .unwrap();
    }

    for (schema_name, filename) in &node.schemas {
        writeln!(code, "            Commands::{schema_name} {{ .. }} => {{").unwrap();
        writeln!(code, "                let schema: serde_json::Value = serde_json::from_str(").unwrap();
        writeln!(code, "                    include_str!(\"{schema_rel}/{filename}\"),").unwrap();
        writeln!(code, "                ).expect(\"embedded JSON Schema must parse\");").unwrap();
        writeln!(code, "                objectiveai_sdk::cli::output::Output::Notification(").unwrap();
        writeln!(code, "                    objectiveai_sdk::cli::output::Notification {{").unwrap();
        writeln!(code, "                        agent_id: None,").unwrap();
        writeln!(code, "                        value: objectiveai_sdk::cli::output::Schema {{ schema }}.into(),").unwrap();
        writeln!(code, "                    }},").unwrap();
        writeln!(code, "                ).emit(handle).await;").unwrap();
        writeln!(code, "                Ok(())").unwrap();
        writeln!(code, "            }}").unwrap();
    }

    code.push_str("        }\n");
    code.push_str("    }\n");
    code.push_str("}\n");

    fs::write(dir.join("mod.rs"), &code).unwrap();

    // Recurse
    for (child_name, child_node) in &node.children {
        generate_module(child_node, &dir.join(child_name), depth + 1);
    }
}

/// Convert snake_case to PascalCase for Rust enum variant names.
fn to_pascal_case(s: &str) -> String {
    s.split('_')
        .map(|seg| {
            let mut chars = seg.chars();
            match chars.next() {
                Some(c) => c.to_uppercase().to_string() + chars.as_str(),
                None => String::new(),
            }
        })
        .collect()
}
